-- Access (ACE/Jet ANSI-92) DDL. Run via ADO (CurrentProject.Connection.Execute), one statement at a time.
CREATE TABLE tblCarType (CarTypeID AUTOINCREMENT PRIMARY KEY, TypeName TEXT(50) NOT NULL, Manufacturer TEXT(50), PMIntervalKm LONG NOT NULL, PMIntervalDays LONG NOT NULL);
CREATE TABLE tblCarStatus (CarStatusID AUTOINCREMENT PRIMARY KEY, StatusName TEXT(30) NOT NULL);
CREATE TABLE tblLocation (LocationID AUTOINCREMENT PRIMARY KEY, LocationName TEXT(50) NOT NULL, LocationType TEXT(20) NOT NULL);
CREATE TABLE tblCar (CarID AUTOINCREMENT PRIMARY KEY, CarNumber TEXT(10) NOT NULL, CarTypeID LONG NOT NULL, CarStatusID LONG NOT NULL, LocationID LONG, InServiceDate DATETIME NOT NULL, CurrentOdometerKm LONG NOT NULL);
CREATE TABLE tblTechnician (TechID AUTOINCREMENT PRIMARY KEY, EmployeeNo TEXT(10) NOT NULL, FullName TEXT(60) NOT NULL, Trade TEXT(30), IsActive YESNO NOT NULL);
CREATE TABLE tblPriority (PriorityID AUTOINCREMENT PRIMARY KEY, PriorityName TEXT(20) NOT NULL, TargetHours LONG NOT NULL);
CREATE TABLE tblWOType (WOTypeID AUTOINCREMENT PRIMARY KEY, WOTypeName TEXT(30) NOT NULL);
CREATE TABLE tblWOStatus (WOStatusID AUTOINCREMENT PRIMARY KEY, WOStatusName TEXT(20) NOT NULL);
CREATE TABLE tblWorkOrder (WOID AUTOINCREMENT PRIMARY KEY, CarID LONG NOT NULL, WOTypeID LONG NOT NULL, PriorityID LONG NOT NULL, WOStatusID LONG NOT NULL, AssignedTechID LONG, OpenedDate DATETIME NOT NULL, DueDate DATETIME, ClosedDate DATETIME, OdometerKm LONG, DefectDescription TEXT(255) NOT NULL, ClosureNotes TEXT(255));
CREATE TABLE tblLabour (LabourID AUTOINCREMENT PRIMARY KEY, WOID LONG NOT NULL, TechID LONG NOT NULL, WorkDate DATETIME NOT NULL, Hours DOUBLE NOT NULL);
CREATE TABLE tblPart (PartID AUTOINCREMENT PRIMARY KEY, PartNumber TEXT(20) NOT NULL, PartName TEXT(60) NOT NULL, UnitCost CURRENCY NOT NULL);
CREATE TABLE tblPartUsed (PartUsedID AUTOINCREMENT PRIMARY KEY, WOID LONG NOT NULL, PartID LONG NOT NULL, Quantity LONG NOT NULL);
CREATE UNIQUE INDEX ux_tblCarType_TypeName ON tblCarType (TypeName);
CREATE UNIQUE INDEX ux_tblCarStatus_StatusName ON tblCarStatus (StatusName);
CREATE UNIQUE INDEX ux_tblLocation_LocationName ON tblLocation (LocationName);
CREATE UNIQUE INDEX ux_tblCar_CarNumber ON tblCar (CarNumber);
CREATE UNIQUE INDEX ux_tblTechnician_EmployeeNo ON tblTechnician (EmployeeNo);
CREATE UNIQUE INDEX ux_tblPriority_PriorityName ON tblPriority (PriorityName);
CREATE UNIQUE INDEX ux_tblWOType_WOTypeName ON tblWOType (WOTypeName);
CREATE UNIQUE INDEX ux_tblWOStatus_WOStatusName ON tblWOStatus (WOStatusName);
CREATE UNIQUE INDEX ux_tblPart_PartNumber ON tblPart (PartNumber);
ALTER TABLE tblCar ADD CONSTRAINT fk_tblCar_CarTypeID FOREIGN KEY (CarTypeID) REFERENCES tblCarType(CarTypeID);
ALTER TABLE tblCar ADD CONSTRAINT fk_tblCar_CarStatusID FOREIGN KEY (CarStatusID) REFERENCES tblCarStatus(CarStatusID);
ALTER TABLE tblCar ADD CONSTRAINT fk_tblCar_LocationID FOREIGN KEY (LocationID) REFERENCES tblLocation(LocationID);
ALTER TABLE tblWorkOrder ADD CONSTRAINT fk_tblWorkOrder_CarID FOREIGN KEY (CarID) REFERENCES tblCar(CarID);
ALTER TABLE tblWorkOrder ADD CONSTRAINT fk_tblWorkOrder_WOTypeID FOREIGN KEY (WOTypeID) REFERENCES tblWOType(WOTypeID);
ALTER TABLE tblWorkOrder ADD CONSTRAINT fk_tblWorkOrder_PriorityID FOREIGN KEY (PriorityID) REFERENCES tblPriority(PriorityID);
ALTER TABLE tblWorkOrder ADD CONSTRAINT fk_tblWorkOrder_WOStatusID FOREIGN KEY (WOStatusID) REFERENCES tblWOStatus(WOStatusID);
ALTER TABLE tblWorkOrder ADD CONSTRAINT fk_tblWorkOrder_AssignedTechID FOREIGN KEY (AssignedTechID) REFERENCES tblTechnician(TechID);
ALTER TABLE tblLabour ADD CONSTRAINT fk_tblLabour_WOID FOREIGN KEY (WOID) REFERENCES tblWorkOrder(WOID);
ALTER TABLE tblLabour ADD CONSTRAINT fk_tblLabour_TechID FOREIGN KEY (TechID) REFERENCES tblTechnician(TechID);
ALTER TABLE tblPartUsed ADD CONSTRAINT fk_tblPartUsed_WOID FOREIGN KEY (WOID) REFERENCES tblWorkOrder(WOID);
ALTER TABLE tblPartUsed ADD CONSTRAINT fk_tblPartUsed_PartID FOREIGN KEY (PartID) REFERENCES tblPart(PartID);
ALTER TABLE tblCar ADD CONSTRAINT ck_tblCar_CurrentOdometerKm CHECK (CurrentOdometerKm >= 0);
ALTER TABLE tblWorkOrder ADD CONSTRAINT ck_tblWorkOrder_OdometerKm CHECK (OdometerKm >= 0);
ALTER TABLE tblLabour ADD CONSTRAINT ck_tblLabour_Hours CHECK (Hours > 0 AND Hours <= 16);
ALTER TABLE tblPart ADD CONSTRAINT ck_tblPart_UnitCost CHECK (UnitCost >= 0);
ALTER TABLE tblPartUsed ADD CONSTRAINT ck_tblPartUsed_Quantity CHECK (Quantity > 0);
ALTER TABLE tblWorkOrder ADD CONSTRAINT ck_tblWorkOrder_dates CHECK (DueDate IS NULL OR DueDate >= OpenedDate);
ALTER TABLE tblWorkOrder ADD CONSTRAINT ck_tblWorkOrder_closed CHECK (ClosedDate IS NULL OR ClosedDate >= OpenedDate);
